window.DIGEST.news.push(...[{"headline": "Model Context Protocol Advances AI Agent Capabilities Across Platforms", "meta": "Today's News · News · 63 posts", "url": "https://x.com/i/trending/2112800075181363436", "summary": "OpenAI enabled WebMCP for ChatGPT Desktop apps; MCP becoming default for agents.", "posts": [], "captured": 1792570742, "post_ids": ["2112701653098930296", "2112769736362889437"]}, {"headline": "Perplexity Launches Fully Local AI Agent for Mac", "meta": "Today's News · News · 1,246 posts", "url": "https://x.com/i/trending/2112604711291400455", "summary": "Fully local Perplexity Computer agent for Apple silicon Macs (>=36GB), offline across Notes/Mail/Messages, hybrid mode.", "posts": [], "captured": 1792571731, "post_ids": ["2112583333825950207", "2112571597798461920"]}, {"headline": "DeepSeek open-sources DeepInfer", "meta": "Explore · Trending · Technology", "url": "https://x.com/search?q=DeepSeek", "summary": "DeepSeek open-sourced DeepInfer, the inference framework behind DeepSeek-V4.1-Flash.", "posts": [], "captured": 1792570742, "post_ids": ["2112476496283775135"]}, {"headline": "AI Playground (Picsart + Seedance 2.5)", "meta": "Explore · Trending · AI Playground", "url": "https://x.com/search?q=AI%20Playground", "summary": "Creators making AI videos with Picsart AI Playground and Seedance 2.5.", "posts": [{"id": "2112804005864726862", "url": "https://x.com/laviniavelle/status/2112804005864726862", "text": "From a creative concept to a visually stunning AI-powered video. \n\nMade with @Picsart AI Playground and Seedance 2.5, bringing ideas to life through natural movement, incredible realism, and eye-catching cinematic details.\n\nWant 10% off Picsart? Comment CODE and I’ll send you your promo code!\n\n#PicsartPartner", "name": "Lavinia", "handle": "laviniavelle", "avatar": "https://pbs.twimg.com/profile_images/2100631432469340160/P18ogXMl_200x200.jpg", "likes": 23, "rts": 3, "replies": 20, "views": 467, "ts": 1792566703, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112803677388095488/vid/avc1/480x714/zAdHa75-aBcVzl-q.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112803677388095488/vid/avc1/720x1072/xMp9kfDudwP41Aie.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112803677388095488/img/Fg-JnmlYEgACtyOu.jpg", "dur": 12}], "quote": null, "reply_to": null}, {"id": "2112814231795941535", "url": "https://x.com/juliaevee/status/2112814231795941535", "text": "It’s incredible to see how AI can transform a simple idea into lifelike visuals!\n\nCreated with @Picsart AI Playground and Seedance 2.5, bringing cinematic scenes, stunning details, and realistic visuals to life.\n\nWant 10% off Picsart? Comment PROMPT and I’ll send you the promo code!\n\n#PicsartPartner", "name": "Julia", "handle": "juliaevee", "avatar": "https://pbs.twimg.com/profile_images/2106420181774090240/-s1skdyv_200x200.jpg", "likes": 35, "rts": 3, "replies": 20, "views": 453, "ts": 1792569141, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112813638545481728/vid/avc1/480x714/gaqhweltCF1SvSwt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112813638545481728/vid/avc1/720x1072/KpndPcT0pi_orAxU.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112813638545481728/img/exSWiL5GqavpLd3u.jpg", "dur": 10}], "quote": null, "reply_to": null}], "captured": 1792570742, "post_ids": ["2112804005864726862", "2112814231795941535"]}, {"headline": "Eagle Corp Launches EAGLE-4, Open-Source Speculative Decoding (~4x vanilla)", "meta": "Explore · Trending · Global Trending #4", "url": "https://x.com/EagleCorp/status/2112660683670323531", "summary": "EAGLE-4 open-source speculative decoding hits 961.6 tok/s on Qwen3.8-27B, ~4x vanilla.", "posts": [], "captured": 1792571731, "post_ids": ["2112660683670323531", "2112660693539573770", "2112680788701409434"]}, {"headline": "Unitree Unveils H2-X Humanoid Robot with Kung Fu Moves", "meta": "Today's News · News · 1,284 posts", "url": "https://x.com/i/trending/2112829126117589392", "summary": "Unitree introduced the H2-X, a 182 cm, 70 kg humanoid with 31 DoF and up to 8 hours endurance.", "posts": [{"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20513, "rts": 2766, "replies": 1427, "views": 4244752, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null}, {"id": "2112829207927746974", "url": "https://x.com/CyberRobooo/status/2112829207927746974", "text": "Unitree H2 is like superhero\n\nFending off an intruder armed with a knife\nLifting a car to rescue someone trapped underneath\nPushing a pedestrian out of the path of an oncoming vehicle\n…\nIn a chaotic and complex real world,\n\nHumanoid robots are needed to protect humanity…", "name": "CyberRobo", "handle": "CyberRobooo", "avatar": "https://pbs.twimg.com/profile_images/1787109582218919936/u85d-MXW_200x200.jpg", "likes": 956, "rts": 149, "replies": 66, "views": 126690, "ts": 1792572712, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112829112951980032/vid/avc1/1280x720/tvIYmp-Z0M7IEFKX.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112829112951980032/vid/avc1/1920x1080/G5_aLQrsRztsybz2.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112829112951980032/img/w3Kr77s-IApo95SP.jpg", "dur": 20}], "quote": {"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20509, "rts": 2766, "replies": 1427, "views": 4243630, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792577415, "post_ids": ["2112819774573179175", "2112757722030719064", "2112829207927746974"]}, {"headline": "Hermes AI Sees Massive Community Updates and Local Model Wins", "meta": "Today's News · Other · 78 posts", "url": "https://x.com/i/trending/2112831851228500185", "summary": "Users added dozens of new Hermes plugins and desktop upgrades; Meta's Muse Glimmer 30B completed 10 tasks on a single RTX 5090; Memory Pane lets people edit what the AI remembers.", "posts": [{"id": "2112782970474139927", "url": "https://x.com/Teknium/status/2112782970474139927", "text": "More game development powers for your Hermes Agent!", "name": "Teknium 🪽", "handle": "Teknium", "avatar": "https://pbs.twimg.com/profile_images/1642401912648777728/2KFikPsE_200x200.jpg", "likes": 413, "rts": 28, "replies": 26, "views": 19613, "ts": 1792561688, "media": [], "quote": {"id": "2112781937303851341", "url": "https://x.com/DecruxR/status/2112781937303851341", "text": "Asked my hermes agent @NousResearch  for a game.\n\nIt made sprites, sound, music, 3D, and a playable Godot build. Then it played the build and caught a crash.\n\n9 tools, 10 skills, offline by default, zero core changes.\n\n@Teknium \nhttps://github.com/DECRUX9812/hermes-plugin-gameforge", "name": "HotDawg", "handle": "DecruxR", "avatar": "https://pbs.twimg.com/profile_images/2101584132044369920/fqPKzLR5_200x200.jpg", "likes": 115, "rts": 10, "replies": 14, "views": 19008, "ts": 1792561442, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112781664468541440/vid/avc1/1280x720/rM_iwg9HqZu2HsIW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112781664468541440/vid/avc1/1920x1080/_hxdehOUmdXneylo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112781664468541440/img/-UfX7XGYCVxC4mF5.jpg", "dur": 60}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792577415, "post_ids": ["2112782970474139927", "2112774433567891465"]}, {"headline": "Ornith-1.5-122B Faces Backlash Over Qwen Attribution and Licensing", "meta": "Explore · Trending · News · 83 posts", "url": "https://x.com/i/trending/2112834712766935305", "summary": "Ornith-1.5-122B (MIT, Oct 20) matches Qwen3.5-122B-A10B architecture exactly; critics cite missing base_model reference and Apache 2.0 attribution.", "posts": [{"id": "2112822741208314258", "url": "https://x.com/MiaAI_lab/status/2112822741208314258", "text": "Run Ornith-1.5-122B on your DGX Spark ✨\n\nUses my Ornith-1.5-122B-EXL3-EAQ 4 bpw quant. Recipe can easily be adapted for the RTX PRO 6000 too.\n\n- Runs on TensorFold\n- 256K context, total 1M KV cache\n- 4 concurrent streams by default\n- 86 GB total memory\n- Uses DFlash2 drafts\n\nDecode speed (thinking off):\n- 52 tok/s on prose, single stream\n- 103 tok/s on code, single stream\n- 90 tok/s on prose, 4 concurrent streams\n\nPrefill is ~2000 tok/s at most context sizes.\n\nOverall I like this model. It feels different from Qwen3.8-Flash-Next and does things its own way. Give it a try!\n\nGet it here:\nhttps://github.com/MiaAI-Lab/Ornith-1.5-122B-TensorFold", "name": "Mia", "handle": "MiaAI_lab", "avatar": "https://pbs.twimg.com/profile_images/2063908041691484160/5XsJBn7I_200x200.jpg", "likes": 193, "rts": 14, "replies": 20, "views": 12390, "ts": 1792571170, "media": [], "quote": null, "reply_to": null}], "captured": 1792577415, "post_ids": ["2112754192532316606", "2112822741208314258"]}, {"headline": "Seedance 2.5 Generates Movie-Like AI Video Clips", "meta": "Today's News · Seedance 2.5 Generates Movie-Like AI Video Clips", "url": "https://x.com/i/trending/2112861314183725086", "summary": "Seedance 2.5 on PixVerse creates hyper-realistic 30-second videos; creators share prompts (tactical woman in warehouse, city driver, swordswoman in misty quarry), praising consistent characters and cinematic lighting. Available to Pro/Premium/Ultra users since August; handles multimodal references and native audio. Some prefer cheaper Wan 3.0 for quick tests while highlighting Seedance's complex-storytelling strength. (Last updated 25 minutes ago at capture.)", "posts": [{"id": "2112801221723431088", "url": "https://x.com/ch_h234/status/2112801221723431088", "text": "AI influencers are getting more realistic with Seedance 2.5. From consistent characters to cinematic visuals, the possibilities are endless. Curious to see what creators build with this.@apob_ai", "name": "Malika Ai", "handle": "ch_h234", "avatar": "https://pbs.twimg.com/profile_images/2052201214700363781/SRvrW_qm_200x200.jpg", "likes": 127, "rts": 39, "replies": 22, "views": 31040, "ts": 1792566039, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112801074306531328/vid/avc1/958x720/dzoGcFSGQO_gsK-H.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112801074306531328/vid/avc1/1112x834/1Ulo4Hr_3s3gRGzG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112801074306531328/img/T1bYAl043lHqQCsa.jpg", "dur": 30}], "quote": {"id": "2112796658329366708", "url": "https://x.com/apob_ai/status/2112796658329366708", "text": "https://x.com/i/article/2112794229835759616", "name": "apob", "handle": "apob_ai", "avatar": "https://pbs.twimg.com/profile_images/1730025089964638208/SOr5IIp-_200x200.jpg", "likes": 21, "rts": 8, "replies": 9, "views": 10505, "ts": 1792564951, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112788650341679275", "url": "https://x.com/ai_explorer25/status/2112788650341679275", "text": "This looks like a scene from a movie, but it was generated with AI. 🤯\n\nThese clips were made with Seedance 2.5, which lets you generate videos up to 30 seconds long. Imagine using it to bring a short film idea to life, create an animated series for YouTube, or turn a product concept into an eye-catching ad.\n\nFor creators, that means more ways to experiment with content for TikTok and YouTube, build an audience, and potentially turn those ideas into income. For small business owners, it’s a way to explore promotional videos without arranging a new shoot for every concept.\n\nThe prompts behind these videos are available on http://Seedance3.tools, so you can reuse them to create similar videos and then put your own spin on them.\n\nYou also get free credits every day. The first 100 users each day receive 200 credits, while everyone else receives 35.\n\nWhich of these videos would you try recreating first?\n\nhttps://seedance3.tools/seedance-2-5?utm_source=NJ", "name": "AI_Explorer", "handle": "ai_explorer25", "avatar": "https://pbs.twimg.com/profile_images/2105533042823659520/S5FX6rIU_200x200.jpg", "likes": 125, "rts": 36, "replies": 15, "views": 25285, "ts": 1792563042, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112787841013215233/vid/avc1/640x360/xrSb4U1vAHZ9Jys3.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112787841013215233/vid/avc1/854x480/EsA4Q5cuTgg5uxak.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112787841013215233/img/qsKIk8P7vKSJo97g.jpg", "dur": 30}], "quote": null, "reply_to": null}], "captured": 1792582516, "post_ids": ["2112760259886407861", "2112801221723431088", "2112788650341679275"]}, {"headline": "Art Platforms Offline for Urgent PHP Security Patches", "meta": "Today's News · Art Platforms Offline for Urgent PHP Security Patches", "url": "https://x.com/i/trending/2112858071798366499", "summary": "Rule34.xxx, DeviantArt, and Pixiv took sites down proactively after two critical PHP vulnerabilities (rated 9.2 severity) surfaced publicly; no hacks/data breaches. Flaws could allow remote code execution, prompting emergency maintenance and a patch release at 14:00 UTC on October 21; users reported outages via Downdetector with memes noting a rare event for long-running sites. Platforms stressed these were preventive and services expected back online soon after verification. (Last updated 38 minutes ago at capture.)", "posts": [{"id": "2112844262790648311", "url": "https://x.com/pixiv/status/2112844262790648311", "text": "【緊急メンテナンスのお知らせ】\n\nサービスの安全性確保のため、以下の日時で緊急メンテナンスを実施いたします。\n\n■日時\n10月21日（水）19:00 〜 10月22日（木）未明（予定）\n※作業状況により終了時刻が前後する場合があります。\n\n■対象サービス\npixiv、ピクシブ百科事典、pixivFANBOX など\n※メンテナンス中は、対象サービスのWebサイトおよびアプリをご利用いただけません。\n\n■その他のサービスへの影響\nメンテナンスに伴い、pixivアカウントを利用する他のサービスでも、一部機能がご利用いただけない可能性があります。\n\n現時点で、不正アクセスやお客様の情報が外部に流出したといった被害は確認されておりません。\n\nご不便をおかけし申し訳ございませんが、ご理解のほどよろしくお願いいたします。", "name": "pixiv", "handle": "pixiv", "avatar": "https://pbs.twimg.com/profile_images/1884128769876860928/TlykAoFy_200x200.jpg", "likes": 113196, "rts": 38447, "replies": 694, "views": 24962088, "ts": 1792576301, "media": [], "quote": null, "reply_to": null}], "captured": 1792582516, "post_ids": ["2112844262790648311", "2112756056678134169", "2112776372812669384"]}, {"headline": "Vangrid Turns Smartphones into On-Demand 3D Mapping Sensors", "meta": "Today's News · Vangrid Turns Smartphones into On-Demand 3D Mapping Sensors", "url": "https://x.com/i/trending/2112855028843401308", "summary": "Vangrid's decentralized network lets people request spatial data for specific spots by locking USDC bounties on Base. Contributors nearby get alerts, capture footage with structured phone sweeps, and submit it—complete with privacy blurring, onchain proofs, and automatic 3D reconstruction. The platform has logged over 1.3 million captures and $620,000 in payouts, targeting needs like robotics training data for interiors and urban nooks that maps miss. After raising $9 million from investors like HashKey and Animoca Brands, it's expanding for autonomous systems while discussions note strong verification but watch for quality and demand in sparse areas. (Last updated 51 minutes ago at capture.)", "posts": [{"id": "2112783639834747009", "url": "https://x.com/DucCryptoX/status/2112783639834747009", "text": "A robot entering a building has to answer two different questions.\n\nWhere am I? That's visual positioning. Niantic Spatial's VPS works it out from what the camera sees instead of GPS, and per GeekWire it's centimeter-level in mapped areas. The company says semantic understanding, where AI reasons about objects instead of just navigating past them, is planned for later this year.\n\nWhat's here right now? That's the question Vangrid's query API is shaped around. Its docs list six observation types (obstacle, occupancy, change, structure, vehicle and vegetation), each returned with a timestamp, a confidence score and a provenance hash, with a default freshness window of 60 seconds.\n\nDifferent questions, and one doesn't replace the other. Ngl, the Vangrid side is a design on paper for now: the API is in early access and its page marks the examples as illustrative. What's live today is commissioned capture, with records on http://explorer.vangrid.io.\n\nhttp://docs.vangrid.io/api/spatial-queries has the page, http://vangrid.io covers the product, and @vangrid_io is the account behind it.  https://x.com/DucCryptoX/status/2112044195548668411/photo/1", "name": "Duc Crypto", "handle": "DucCryptoX", "avatar": "https://pbs.twimg.com/profile_images/2098109471650426881/r7Y6Vti5_200x200.jpg", "likes": 467, "rts": 11, "replies": 548, "views": 3041, "ts": 1792561848, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HU98_1_bgAAgi_j.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792582516, "post_ids": ["2112763331467444408", "2112529276633247757", "2112783639834747009"]}, {"headline": "NVIDIA Unveils OpenShell to Secure AI Agents at Scale", "meta": "Today's News · Trending now · News · 125 posts (ticked to 125 while in the story)", "url": "https://x.com/i/trending/2112874286364959108", "summary": "NVIDIA's OpenShell Reference Architecture sets strict boundaries for AI agents, using hardware-isolated security to quarantine violators in milliseconds. Combines Vera Rubin systems for inference, Vera CPUs for tasks, and Sentry software on BlueField-4 DPUs for enforcement, with an open-source runtime for deny-by-default access controls. 100+ partners (Anthropic, Microsoft, SpaceX, …) are integrating it from data centers to edge devices (manufacturing, healthcare, robotics). Jensen Huang emphasized capability and safety must advance hand-in-hand.", "posts": [{"id": "2112847277282721888", "url": "https://x.com/nvidia/status/2112847277282721888", "text": "Jensen introduces the OpenShell Reference Architecture to help businesses set boundaries for AI agents and stop them when they step outside those boundaries.\n\nSecuring agents around the world. 🔒", "name": "NVIDIA", "handle": "nvidia", "avatar": "https://pbs.twimg.com/profile_images/1828904711124078593/SRvCZSfQ_200x200.jpg", "likes": 533, "rts": 66, "replies": 105, "views": 70921, "ts": 1792577020, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112847115508412416/vid/avc1/1280x720/xgq8VapRRLfXEsF8.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112847115508412416/vid/avc1/3840x2160/zl7kZz9UCY7e8-9-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112847115508412416/img/FarKxRi0vL150Mo-.jpg", "dur": 17}], "quote": null, "reply_to": null}, {"id": "2112846708527018339", "url": "https://x.com/NVIDIAAI/status/2112846708527018339", "text": "AI agents need fast tool calls and security controls they can’t rewrite.\n\nNVIDIA OpenShell Reference Architecture combines the compute to run agents at scale with runtime controls that govern their access to tools and data.\n\nSee how the hardware and software work together: https://nvda.ws/4BiJBfY", "name": "NVIDIA AI", "handle": "NVIDIAAI", "avatar": "https://pbs.twimg.com/profile_images/2055340743552831488/me-KUIug_200x200.png", "likes": 260, "rts": 36, "replies": 35, "views": 16006, "ts": 1792576884, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112846318515408896/vid/avc1/1280x720/kViK9aJEMDXxqWPo.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112846318515408896/vid/avc1/3840x2160/vcsQ5tJo0Ff7kqVL.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112846318515408896/img/5fB96WXes36fRuvq.jpg", "dur": 184}], "quote": null, "reply_to": null}], "captured": 1792617099, "post_ids": ["2112847277282721888", "2112846708527018339"]}, {"headline": "DeepSeek Open-Sources DeepInfer for Efficient V4.1-Flash Inference", "meta": "Today's News · Trending now · News · 242 posts (ticked to 249 while in the story)", "url": "https://x.com/i/trending/2112874286495023318", "summary": "DeepInfer offers optimized kernels, speculative decoding, and NVIDIA/Huawei hardware support, running ~155T tokens/day on one cluster with strong cache efficiency. The V4.1-Flash-1017 model has 763B parameters and 1M-token context with top coding-benchmark scores; weights on Hugging Face under MIT. Praised for efficiency (~$38 revenue/GPU-hour), but some call it 'open weights' rather than fully open source since training data/code remain private. Platforms like B.AI are already discounting access.", "posts": [{"id": "2112812782508794105", "url": "https://x.com/MiaAI_lab/status/2112812782508794105", "text": "NVIDIA just released Flare, a local inference server built for DGX Spark and RTX Blackwell GPUs\n\n- Built for long chats, agents and tool calls\n- Serves from Rust, no Python\n- Plans memory up front\n- FP8 KV cache by default\n\nInteresting timing... right around when DeepSeek open-sourced their inference engine.\n\nLink below.", "name": "Mia", "handle": "MiaAI_lab", "avatar": "https://pbs.twimg.com/profile_images/2063908041691484160/5XsJBn7I_200x200.jpg", "likes": 848, "rts": 67, "replies": 56, "views": 57831, "ts": 1792568796, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVI2l9BWgAAgQEV.png?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112801561063887286", "url": "https://x.com/alex_verem/status/2112801561063887286", "text": "DeepSeek sold you a lie.\n\nIts new model, V4.1-Flash, is being sold as \"open source\".\n\nIt's not.\n\nYou can download it free, with no sign-up and use it in your business which sounds open source.\n\nBut you can't access the code they used to train it or the data they trained it on.\n\nWithout those, nobody can check how it was made or rebuild it and it’s over 700 billion parameters, so you can’t even run it on your laptop.\n\nWhen you can build a business on something but can’t see how it was made, the right term is \"open weights\".\n\nCall it what it is.", "name": "Alex Veremeyenko", "handle": "alex_verem", "avatar": "https://pbs.twimg.com/profile_images/2066549522285649920/ZbW4cujK_200x200.jpg", "likes": 281, "rts": 12, "replies": 420, "views": 238567, "ts": 1792566120, "media": [], "quote": {"id": "2112476496283775135", "url": "https://x.com/deepseek_ai/status/2112476496283775135", "text": "🚀 Introducing DeepInfer, our in-house inference framework, now fully open source!\n\nPowering DeepSeek-V4.1-Flash at scale with high throughput and low latency. We’re sharing our production stack to help the community lower compute costs, reduce energy use, and make AI more affordable.\n\n🔗 http://github.com/deepseek-ai/DeepInfer\n\n1/4", "name": "DeepSeek", "handle": "deepseek_ai", "avatar": "https://pbs.twimg.com/profile_images/1717417613775757312/Uk1zNOj4_200x200.jpg", "likes": 41700, "rts": 4711, "replies": 1531, "views": 6291122, "ts": 1792488619, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792617099, "post_ids": ["2112812782508794105", "2112801561063887286"]}, {"headline": "PHP Foundation Releases Urgent Fix for Critical Vulnerabilities", "meta": "Today's News · Trending now · News · 23K posts", "url": "https://x.com/i/trending/2112867444712947887", "summary": "The vulnerabilities, rated CVSS 9.2 and tied to session.upload_progress, have sparked proof-of-concept exploits and active attacks, prompting Cloudflare to roll out firewall rules for all users as a temporary shield. Sites including OBS streaming, GrapheneOS forums, and Dutch government portals have gone offline as a precaution while awaiting the patch. Officials from the UK, Australia, and Japan urge immediate updates or shutdowns, with community workarounds like disabling the feature in php.ini offered until the official release.", "posts": [{"id": "2112811965735202970", "url": "https://x.com/dok2001/status/2112811965735202970", "text": "PHP sites behind Cloudflare already have an initial set of WAF rules deployed for the known exploit vectors in these vulnerabilities. The rules are available to all customers, including free.\n\nWe are seeing early attacks emerging and are updating mitigations as new vectors show up.\n\nThis is a STOPGAP only. Patch as soon as @ThePHPF releases the update at 14:00 UTC today.", "name": "Dane Knecht 🦭", "handle": "dok2001", "avatar": "https://pbs.twimg.com/profile_images/1933364396434001920/nNinLkYf_200x200.jpg", "likes": 5269, "rts": 867, "replies": 86, "views": 707098, "ts": 1792568601, "media": [], "quote": {"id": "2112633155631108544", "url": "https://x.com/ThePHPF/status/2112633155631108544", "text": "The PHP security team is giving advance notice: Upcoming security release Wed, Oct 21st 2026, 14:00UTC, two critical vulnerabilities, both rated CVSSv4 9.2.\n\nPHP users are encouraged to prepare to update. Earlier release if details become public or active exploit evidence.", "name": "The PHP Foundation", "handle": "ThePHPF", "avatar": "https://pbs.twimg.com/profile_images/1462756177696206854/YcHaTzic_200x200.jpg", "likes": 18253, "rts": 4126, "replies": 335, "views": 6816319, "ts": 1792525969, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792617099, "post_ids": ["2112756056678134169", "2112811965735202970", "2112633155631108544"]}, {"headline": "NVIDIA CEO Praises Nebius as Key Player in Europe's AI Growth", "meta": "Today's News · News · 1.7K posts", "url": "https://x.com/i/trending/2112877780593484093", "summary": "Jensen Huang at GTC Berlin praised Nebius and IREN as neocloud partners for NVIDIA's DSX AI factory platform; Vera Rubin is in full production.", "posts": [{"id": "2112842412515021115", "url": "https://x.com/kimmonismus/status/2112842412515021115", "text": "NVIDIA just announced DSX POD. \n\nThis is a bigger deal than most people realize, because it solves one of the biggest bottlenecks: scaling! Instead of taking months to build out a data center, you can now scale compute capacity in just a few days!", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 2785, "rts": 217, "replies": 145, "views": 196958, "ts": 1792575860, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112840613057945600/vid/avc1/720x1280/_Y_ugm-z_If9Hism.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112840613057945600/vid/avc1/1080x1920/535o4LHP_JAM7R7s.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112840613057945600/img/KaRlX4FDHnH1PCfR.jpg", "dur": 98}], "quote": null, "reply_to": null}, {"id": "2112843581287231650", "url": "https://x.com/nvidia/status/2112843581287231650", "text": "Doing what was previously unimaginable 🚀", "name": "NVIDIA", "handle": "nvidia", "avatar": "https://pbs.twimg.com/profile_images/1828904711124078593/SRvCZSfQ_200x200.jpg", "likes": 3124, "rts": 206, "replies": 61, "views": 139406, "ts": 1792576139, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/1280x720/Tk77LptLZ4A3F2cn.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/3840x2160/QvKR7U2d7mUCIB98.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112843085403099136/img/IGsh-H3rd_Z9uBks.jpg", "dur": 41}], "quote": null, "reply_to": null}], "captured": 1792588923, "post_ids": ["2112842412515021115", "2112843581287231650"]}, {"headline": "Grok Bot Helps Solo Founders Build AI Teams", "meta": "Today's News · News · 415 posts", "url": "https://x.com/i/trending/2112877780664750550", "summary": "Grok Bot lets solo founders create 24/7 AI agents; open-source spin-off Grok Bot OS released.", "posts": [{"id": "2112816157682204822", "url": "https://x.com/ryangrowthh/status/2112816157682204822", "text": "Grok Bot is basically AGI for 𝕏 content.\n\nIt helped me generate ~2M views in my first 2 weeks on the platform.\n\nHere are 10 cool use cases:\n\n1. 𝕏 Researcher Bot: Scans outlier content overnight and delivers a full report in the morning with content ideas that align with my niche.\n\n2. Chief of Staff: My main bot that manages all my MCP connections, routines, etc.\n\n3. X Article Tracker: A Bot dedicated to tracking all my article ideas (I can just text my bot instead of logging stuff in Notion).\n\n4. Analytics Coach: Sends me a daily report of my impressions (+ all my replies included)\n\n5. Competitor Watch: Tracks my X lists for alpha\n\n6. Bookmarks Brain: Logs all my bookmarks + sends me a daily summary of posts I might've forgotten about (also summarizes articles/long-form content) \n\n7. Quote Post Scout: Finds high-performing posts in my niche worth quote-posting with my own take.\n\n8. Fact Checker: Double-checks stats and claims in other people's posts \n\n9. Sparring Bot: A Bot dedicated to \"sparring\" 𝕏 ideas \n\n10. Banner and Visual Prompter: Writes image prompts for my article banners and post graphics\n\nIt would also be cool to launch a Bot to hunt paid promos/sponsors.\n\nCurious how you guys are using Bot for daily content?", "name": "Ryan", "handle": "ryangrowthh", "avatar": "https://pbs.twimg.com/profile_images/2097149271011438592/Q9mfZr5D_200x200.jpg", "likes": 1522, "rts": 56, "replies": 154, "views": 128155, "ts": 1792569600, "media": [], "quote": null, "reply_to": null}, {"id": "2112855560550855042", "url": "https://x.com/mikepat711/status/2112855560550855042", "text": "It’s actually insane to me that less than one million people use Grok Bot. This shit is a critical component to my life now and almost nobody even has this experience yet. Insane. \n\n2 million MAU by January. \n\nI need Thanksgiving promo subs. Christmas gift cards. Referral incentives. \n\nHelp me help you, @SpaceXSI", "name": "Mike P", "handle": "mikepat711", "avatar": "https://pbs.twimg.com/profile_images/2006022578251419649/krgWrQpt_200x200.jpg", "likes": 228, "rts": 4, "replies": 45, "views": 9140, "ts": 1792578995, "media": [], "quote": null, "reply_to": null}], "captured": 1792588923, "post_ids": ["2112816157682204822", "2112768301046907168", "2112855560550855042"]}, {"headline": "OpenAI Brings GPT-6 Astra and Codex to Google Cloud Marketplace", "meta": "Today's News · News · 182 posts", "url": "https://x.com/i/trending/2112885093610229938", "summary": "OpenAI frontier models incl. GPT-6 Astra and Codex coming to Google Cloud Marketplace and Model Garden.", "posts": [{"id": "2112877180237582775", "url": "https://x.com/DeItaone/status/2112877180237582775", "text": "OPENAI AND GOOGLE STRIKE MAJOR AI DISTRIBUTION DEAL\n\nOpenAI will bring its frontier AI models, including GPT-6 Astra, and Codex to Google Cloud in the coming weeks.\n\nEnterprise customers will be able to purchase them through Google Cloud Marketplace, using existing cloud spending commitments.\n\nThe agreement follows OpenAI's expansion to AWS after its exclusive Microsoft distribution arrangement ended.", "name": "*Walter Bloomberg", "handle": "DeItaone", "avatar": "https://pbs.twimg.com/profile_images/2088360110095478784/El9anzXH_200x200.jpg", "likes": 1219, "rts": 109, "replies": 110, "views": 264317, "ts": 1792584149, "media": [], "quote": null, "reply_to": null}, {"id": "2112884000507175359", "url": "https://x.com/edzitron/status/2112884000507175359", "text": "I guess this makes sense considering OpenAI already spends like $10bn a year on Google cloud", "name": "Ed Zitron", "handle": "edzitron", "avatar": "https://pbs.twimg.com/profile_images/2070326703281553408/ILxQjQF7_200x200.jpg", "likes": 210, "rts": 13, "replies": 10, "views": 15593, "ts": 1792585775, "media": [], "quote": {"id": "2112877180237582775", "url": "https://x.com/DeItaone/status/2112877180237582775", "text": "OPENAI AND GOOGLE STRIKE MAJOR AI DISTRIBUTION DEAL\n\nOpenAI will bring its frontier AI models, including GPT-6 Astra, and Codex to Google Cloud in the coming weeks.\n\nEnterprise customers will be able to purchase them through Google Cloud Marketplace, using existing cloud spending commitments.\n\nThe agreement follows OpenAI's expansion to AWS after its exclusive Microsoft distribution arrangement ended.", "name": "*Walter Bloomberg", "handle": "DeItaone", "avatar": "https://pbs.twimg.com/profile_images/2088360110095478784/El9anzXH_200x200.jpg", "likes": 1219, "rts": 109, "replies": 110, "views": 264317, "ts": 1792584149, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112881626179101115", "url": "https://x.com/gabrielchua/status/2112881626179101115", "text": "OpenAI models are coming to Google Cloud ☁️", "name": "Gabriel Chua", "handle": "gabrielchua", "avatar": "https://pbs.twimg.com/profile_images/2000727056112607232/WnaCabQi_200x200.jpg", "likes": 242, "rts": 12, "replies": 18, "views": 9512, "ts": 1792585209, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJ2otQaUAASHCz.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792588923, "post_ids": ["2112877180237582775", "2112884000507175359", "2112881626179101115"]}, {"headline": "Hints Emerge of Anthropic's Claude Fable 5.5 in Code Repositories", "meta": "Today's News · News · 371 posts", "url": "https://x.com/i/trending/2112881263677952469", "summary": "'Fable 5.5' co-author credit surfaced in a public GitHub PR, a pre-launch pattern; Anthropic silent.", "posts": [{"id": "2112790241648029893", "url": "https://x.com/maurice_build/status/2112790241648029893", "text": "\"I get a lot more done with Claude\"\n\nNO, you don't. Unless you are using the 20x subscription.\n\nWith the current $100 subscription, you get the following monthly API equivalents: \n\nOpus 5.5 | Claude Max 5x = $5,725 \n6.1 Sol | ChatGPT Pro = $1,055 \nArgon | Google AI Ultra = $300\n\nIf you compare the cost of completing a task at the max reasoning level, you will find that you get more tasks done with your GPT subscription:\n\nSol 6.1 | $1,055/ $0.72 ≈ 1,465\nOpus 5.5 | $5,725/ $5.98 ≈ 957 \nArgon | $300 ÷ $1.99 ≈ 151\n\nEven with high reasoning, GPT does beat Claude.", "name": "Maurice", "handle": "maurice_build", "avatar": "https://pbs.twimg.com/profile_images/2051962217210269698/1RYcVbJ2_200x200.jpg", "likes": 176, "rts": 7, "replies": 157, "views": 62003, "ts": 1792563422, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVIjh0oWAAAxY2Z.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112884674301411415", "url": "https://x.com/CodeWithAmann/status/2112884674301411415", "text": "We already have opus 5.5\n\nDo we really need fable 5.5 ?", "name": "Aman 🧋", "handle": "CodeWithAmann", "avatar": "https://pbs.twimg.com/profile_images/2109998553426984961/xJz5yaNw_200x200.jpg", "likes": 68, "rts": 4, "replies": 48, "views": 1903, "ts": 1792585936, "media": [], "quote": null, "reply_to": null}, {"id": "2112820819608945136", "url": "https://x.com/mark_k/status/2112820819608945136", "text": "\"Fable 5.5\" is showing up in public GitHub commits now. A T3 Code pull request merged on October 20 includes October 17 commits carrying the credit \"Co-authored-by: Fable 5.5 \"noreply@anthropic.com\" (mailto:noreply@anthropic.com)\". The changes fix an authentication issue affecting locally hosted clients.\n\nThat fits the reports of partners testing Anthropic's next model. One caveat: anyone can edit a Git commit's coauthor field, so the credit alone cannot prove which model wrote the code. Anthropic still hasn't officially announced Fable 5.5.", "name": "Mark Kretschmann", "handle": "mark_k", "avatar": "https://pbs.twimg.com/profile_images/1923114794804039680/HMfSchLD_200x200.jpg", "likes": 155, "rts": 7, "replies": 22, "views": 13985, "ts": 1792570712, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVI_VYyXgAAGek5.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792588923, "post_ids": ["2112790241648029893", "2112884674301411415", "2112820819608945136"]}, {"headline": "IREN Plans 300MW AI Data Center Campus in Spain's Badajoz", "meta": "Today's News · News · 551 posts", "url": "https://x.com/i/trending/2112877780547330384", "summary": "300MW AI data center campus in Badajoz announced at GTC Berlin, targeting 2028, NVIDIA DSX compatible.", "posts": [{"id": "2112878009552105973", "url": "https://x.com/IREN_Ltd/status/2112878009552105973", "text": "IREN is advancing sovereign AI in Europe, bringing together its European data center capacity and managed cloud services for customers seeking more choice over where their AI workloads run and how their data and infrastructure are managed.\n\nAnnounced today at NVIDIA GTC Berlin, IREN has established IREN Europe and appointed Ángel Corcóstegui as Chair of the newly established board of directors.\n\nIREN also secured the civil works license for its planned 300MW campus in Badajoz, Spain. Following the completion of its acquisition of Mirantis, IREN’s software capabilities include workload isolation and operational controls that can help customers address data residency, security and governance requirements.\n\nRead more: https://iren.gcs-web.com/static-files/1c72624b-c8f0-4866-afd4-06ae0de59654", "name": "IREN", "handle": "IREN_Ltd", "avatar": "https://pbs.twimg.com/profile_images/1758256199156580352/Jy9BjPKF_200x200.jpg", "likes": 1734, "rts": 156, "replies": 59, "views": 108390, "ts": 1792584347, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJyNA-XIAAfYIJ.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112872607049715966", "url": "https://x.com/StockSavvyShay/status/2112872607049715966", "text": "$IREN just created IREN Europe with plans for a 300 MW AI campus in Spain targeting operations in 2028.\n\nThe move comes as Europe pushes for greater control over its AI infrastructure giving IREN an opportunity to serve customers who want their data and compute managed locally.", "name": "Shay Boloor", "handle": "StockSavvyShay", "avatar": "https://pbs.twimg.com/profile_images/1878129937737187328/DnEflT4L_200x200.jpg", "likes": 1173, "rts": 96, "replies": 43, "views": 63027, "ts": 1792583059, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJuUn9aAAAyUfQ.png?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVJuVM9bkAAUA9s.png?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792588923, "post_ids": ["2112878009552105973", "2112872607049715966"]}, {"headline": "NVIDIA Unveils DSX POD for Rapid AI Factory Deployment", "meta": "Explore · Trending · News", "url": "https://x.com/i/trending/2112897167996194839", "summary": "At GTC Berlin NVIDIA announced DSX POD, a factory-built Vera Rubin AI system cutting deployment from six months to 14 days; Dell, HPE, Lenovo ship from early 2027.", "posts": [{"id": "2112843581287231650", "url": "https://x.com/nvidia/status/2112843581287231650", "text": "Doing what was previously unimaginable 🚀", "name": "NVIDIA", "handle": "nvidia", "avatar": "https://pbs.twimg.com/profile_images/1828904711124078593/SRvCZSfQ_200x200.jpg", "likes": 3124, "rts": 206, "replies": 61, "views": 139406, "ts": 1792576139, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/1280x720/Tk77LptLZ4A3F2cn.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112843085403099136/vid/avc1/3840x2160/QvKR7U2d7mUCIB98.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112843085403099136/img/IGsh-H3rd_Z9uBks.jpg", "dur": 41}], "quote": null, "reply_to": null}, {"id": "2112842412515021115", "url": "https://x.com/kimmonismus/status/2112842412515021115", "text": "NVIDIA just announced DSX POD. \n\nThis is a bigger deal than most people realize, because it solves one of the biggest bottlenecks: scaling! Instead of taking months to build out a data center, you can now scale compute capacity in just a few days!", "name": "Chubby♨️", "handle": "kimmonismus", "avatar": "https://pbs.twimg.com/profile_images/1728327996375719936/RW7VBJfD_200x200.jpg", "likes": 2785, "rts": 217, "replies": 145, "views": 196958, "ts": 1792575860, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112840613057945600/vid/avc1/720x1280/_Y_ugm-z_If9Hism.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112840613057945600/vid/avc1/1080x1920/535o4LHP_JAM7R7s.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112840613057945600/img/KaRlX4FDHnH1PCfR.jpg", "dur": 98}], "quote": null, "reply_to": null}], "captured": 1792601076, "post_ids": ["2112843581287231650", "2112842412515021115"]}, {"headline": "DeviantArt and Pixiv Go Offline for Urgent PHP Security Patches", "meta": "Today's News · Trending now · News", "url": "https://x.com/i/trending/2112888760463442426", "summary": "DeviantArt announced temporary downtime for maintenance, ending later that day after installing software patches. Pixiv scheduled emergency maintenance from 19:00 JST 2026-10-21 into 2026-10-22 across its main site, encyclopedia, and pixivFANBOX, with no confirmed breaches. The outages are tied to PHP Foundation warnings on two high-severity (CVSS 9.2) vulnerabilities; other sites such as Fur Affinity took similar precautionary steps. Users were frustrated by the timing, while the platforms stressed the brief interruptions ensure long-term security.", "posts": [{"id": "2112844262790648311", "url": "https://x.com/pixiv/status/2112844262790648311", "text": "【緊急メンテナンスのお知らせ】\n\nサービスの安全性確保のため、以下の日時で緊急メンテナンスを実施いたします。\n\n■日時\n10月21日（水）19:00 〜 10月22日（木）未明（予定）\n※作業状況により終了時刻が前後する場合があります。\n\n■対象サービス\npixiv、ピクシブ百科事典、pixivFANBOX など\n※メンテナンス中は、対象サービスのWebサイトおよびアプリをご利用いただけません。\n\n■その他のサービスへの影響\nメンテナンスに伴い、pixivアカウントを利用する他のサービスでも、一部機能がご利用いただけない可能性があります。\n\n現時点で、不正アクセスやお客様の情報が外部に流出したといった被害は確認されておりません。\n\nご不便をおかけし申し訳ございませんが、ご理解のほどよろしくお願いいたします。", "name": "pixiv", "handle": "pixiv", "avatar": "https://pbs.twimg.com/profile_images/1884128769876860928/TlykAoFy_200x200.jpg", "likes": 113196, "rts": 38447, "replies": 694, "views": 24962088, "ts": 1792576301, "media": [], "quote": null, "reply_to": null}, {"id": "2112795132374495687", "url": "https://x.com/expokun/status/2112795132374495687", "text": "【各位】今夜23時、ネットの裏側で「15分間の極限攻防」が始まります。\n\n本日10/21、Webの約8割の土台である「PHP」に致命的な欠陥（CVSS 9.2の超危険度）が発覚し、修正プログラムが日本時間の今夜23時に緊急公開されます。\n\n解説と個人としての緊急対策を取り急ぎ。\n\nーーー（読み飛ばしてOK）ーーー\n◆ どういう欠陥か？（攻撃の仕組み）サーバーにデータを処理させる「入力チェック機能（パース処理）」の境界線の不備です。本来は拒否されるべき「不正に加工されたリクエスト」を正常なデータだと誤認して読み込んでしまう構造的欠陥です。\n◆ そこを突くと何ができるのか？① 遠隔でのコマンド強制実行（RCE）外部から一切のログイン手順を飛ばし、サーバー内で「最高管理者コマンド」を勝手に実行できます。② データベースの完全強奪サイト内の全会員データ・暗号化パスワード・決済履歴を、防御を無視して一括で外部へ抜き出せます。③ サーバーの「踏み台」化・ランサムウェア化サイトを乗っ取ってマルウェアを植え付け、そこを拠点に他の企業や個人へ攻撃を拡大させます。\nーーーーーーーーーーーーーーー\n\n恐ろしいのはここから。パッチが出た瞬間、攻撃者側はAIを使って「どこが直されたか」を一瞬で解析し、わずか15分以内に全世界の脆弱なサイトへ自動攻撃を仕掛けると予測されています。\n\n「エンジニアの話でしょ？」ではありません。PHPはネット通販や予約サイト、企業システムの「心臓部」です。ここが破られると、サービス停止だけでなく、過去に登録したあなたの名前、住所、クレカ情報、パスワードが大量流出します。\n\n⚠️【今すぐできる自衛3つ】\n① 使い回しパスワードの緊急変更（漏洩した瞬間に別サービスへ侵入される連鎖を防ぐ）\n② 主要サービスで「二要素認証（2FA）」をON\n③ 「メンテナンス通知」や「パスワード再設定」を騙る詐欺メールに警戒\n\n今夜は全国のエンジニアが徹夜で防御戦に入ります。自分と家族の身を守るために、ブクマして備えてください。身近な人にもシェアを。\n\n今晩からサイバー攻撃のフェーズが変わります。\n明日の景色はわかりません。", "name": "三日前", "handle": "expokun", "avatar": "https://pbs.twimg.com/profile_images/2102859842910302208/cEr_BXN4_200x200.jpg", "likes": 77899, "rts": 33285, "replies": 212, "views": 28365614, "ts": 1792564588, "media": [], "quote": null, "reply_to": null}], "post_count_at_open_posts_approx": "40.5K", "captured": 1792591323, "post_ids": ["2112844262790648311", "2112795132374495687"]}, {"headline": "OpenAI AI Agents Uncover Brain Disease Leads in 32 Minutes", "meta": "Today's News · Trending now · News · 462 posts", "url": "https://x.com/i/trending/2112910608761078215", "summary": "Working with PerturbAI and Scripps Research, OpenAI's GPT-Rosalind agents analyzed gene disruptions, linked the DCTN1 gene to cholesterol transport issues in neurons (human experts ranked high for follow-up); same data revealed why TSC2 mutations cause more severe tuberous sclerosis than TSC1; announcement came alongside OpenAI's acquisition of Orchestra Bio, whose platform will integrate with Rosalind. (Grok summary, last updated ~34 minutes ago)", "posts": [{"id": "2112899854569762936", "url": "https://x.com/OpenAI/status/2112899854569762936", "text": "GPT-Rosalind surfaced a new lead for drug discovery: could restoring cholesterol transport protect neurons from degeneration?\n\nDCTN1 is a gene linked to Perry syndrome, a rare neurodegenerative disorder. In mouse-brain data, disrupting it increased expression of genes involved in making cholesterol. GPT-Rosalind suggested a possible explanation: cholesterol may not be reaching where neurons need it.\n\nThat gives scientists a specific mechanism to test and, if confirmed, a direction for developing new treatments for neurodegenerative disorders.\n\nWith @perturbai_tx and @scrippsresearch, a team of thousands of GPT-Rosalind agents worked in parallel, connecting gene-expression results from millions of mouse brain cells with scientific literature in just 32 minutes. We’re now expanding this collaboration to identify new drug targets.\n\nhttps://openai.com/index/scaling-ai-research-for-complex-biological-data/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 6098, "rts": 626, "replies": 354, "views": 1121758, "ts": 1792589555, "media": [], "quote": null, "reply_to": null}, {"id": "2112903923837137226", "url": "https://x.com/IterIntellectus/status/2112903923837137226", "text": "> thousands of agents\n> ~40,000 scientific papers read\n> 32 minutes\n> found new potential mechanisms worth investigating for Parkinson-like neurodegenerative diseases\n\nwork that would have taken human researchers months to a year, done in just 32 minutes\n\ni genuinely don't think people understand what is coming for biotech", "name": "vittorio", "handle": "IterIntellectus", "avatar": "https://pbs.twimg.com/profile_images/2009602429478633472/8lMkYuep_200x200.jpg", "likes": 4668, "rts": 295, "replies": 103, "views": 125815, "ts": 1792590525, "media": [], "quote": {"id": "2112899854569762936", "url": "https://x.com/OpenAI/status/2112899854569762936", "text": "GPT-Rosalind surfaced a new lead for drug discovery: could restoring cholesterol transport protect neurons from degeneration?\n\nDCTN1 is a gene linked to Perry syndrome, a rare neurodegenerative disorder. In mouse-brain data, disrupting it increased expression of genes involved in making cholesterol. GPT-Rosalind suggested a possible explanation: cholesterol may not be reaching where neurons need it.\n\nThat gives scientists a specific mechanism to test and, if confirmed, a direction for developing new treatments for neurodegenerative disorders.\n\nWith @perturbai_tx and @scrippsresearch, a team of thousands of GPT-Rosalind agents worked in parallel, connecting gene-expression results from millions of mouse brain cells with scientific literature in just 32 minutes. We’re now expanding this collaboration to identify new drug targets.\n\nhttps://openai.com/index/scaling-ai-research-for-complex-biological-data/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 6099, "rts": 626, "replies": 354, "views": 1121758, "ts": 1792589555, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112899856205578486", "url": "https://x.com/OpenAI/status/2112899856205578486", "text": "In the same mouse-brain dataset, GPT-Rosalind found a possible clue to why TSC2 mutations tend to cause more severe tuberous sclerosis than TSC1 mutations.\n\nThe two genes work together to regulate mTOR. Yet in one group of cerebellar neurons, disrupting TSC2 changed the expression of dozens of genes, including genes involved in neuronal communication. Disrupting TSC1 had little effect on gene expression in the same cell type.\n\nExisting treatments already target mTOR. Do they reverse these changes, or is there more to TSC2’s role in these neurons?", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 614, "rts": 28, "replies": 21, "views": 100838, "ts": 1792589556, "media": [], "quote": null, "reply_to": "2112899854569762936"}], "captured": 1792595382, "post_ids": ["2112899854569762936", "2112903923837137226", "2112899856205578486"]}, {"headline": "Legora Raises $550M at $8.8B Valuation for Legal AI Platform", "meta": "Today's News · Trending now · News · 82 posts", "url": "https://x.com/i/trending/2112905984255336723", "summary": "Legora raised $550M Series E led by Atreides at $8.8B valuation; 140,000 legal pros use its agentic platform; revenue over $200M.", "posts": [{"id": "2112888145985380394", "url": "https://x.com/davidneckstein/status/2112888145985380394", "text": "We raised $550M at an $8.8B valuation.\n\nA cap table tells you how a company intends to build. We built this round around investors with a long time horizon: established long-term holders, plus institutions that work with law firms and in-house legal teams every day and have a close view of where legal work is heading.\n\n@Atreidesmgmt / @GavinSBaker led. @BaronCapital, @CapitalGroup, @Fidelity, @GladeBrookCap and @jpmorgan are new. Every major existing investor is in again.\n\nShort-horizon money asks for growth at any price. Long-horizon money asks whether the business holds up. We’d rather deliver on the second question. ARR is past $200M, and the next $100M took us less than six months. Gross margin is healthy and the cost structure gets stronger as we scale. Patient investors let us keep it that way, because nobody is asking us to trade one for the other.\n\nThank you to every investor who joined, and to the customers and team who bet on us.\n\nAdding a picture from when we signed the term sheet. \n\nBack to work. LFG!", "name": "David Eckstein", "handle": "davidneckstein", "avatar": "https://pbs.twimg.com/profile_images/509770564123111424/aMuq_28G_200x200.jpeg", "likes": 181, "rts": 10, "replies": 18, "views": 14375, "ts": 1792586764, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJpJd4WMAETe_f.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112891879440138480", "url": "https://x.com/WeAreLegora/status/2112891879440138480", "text": "We have raised a $550 million Series E at a $8.8B valuation to accelerate our growth in the U.S. and globally, and deepen investment in the Legora aOS, our agentic operating system for legal work.\n\n@Atreidesmgmt leads this round, alongside new investors @BaronCapital, @CapitalGroup, @Fidelity,  @GladeBrookCap, and @jpmorgan. Every major existing investor is participating. We’re grateful to have partners who share our ambition and our long-term view.\n\nWe build AI together with the people who use it. That’s always been our approach. Our customers help shape what we build, pushing us to go further on the work that matters.\n\nThis is the most exciting time in history to be a lawyer, and we’re lucky to be in the middle of it.\nRead the full release: https://legora.com/blog/series-e", "name": "Legora", "handle": "WeAreLegora", "avatar": "https://pbs.twimg.com/profile_images/2035991206371774464/M5zQPOWU_200x200.jpg", "likes": 142, "rts": 18, "replies": 11, "views": 10557, "ts": 1792587654, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112889534920728576/vid/avc1/720x900/ZtFaWJw-zOhErgPE.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112889534920728576/vid/avc1/1080x1350/OidI3n-Rf4d508SA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112889534920728576/img/GJtpaDcy-Rywu3sG.jpg", "dur": 50}], "quote": null, "reply_to": null}], "captured": 1792594418, "post_ids": ["2112888145985380394", "2112891879440138480"]}, {"headline": "NVIDIA and UW Release RFD4-Proteina for Advanced Protein Design", "meta": "Explore · News · Trending now · News · 267 posts", "url": "https://x.com/i/trending/2112910613542481933", "summary": "RFD4-Proteina, unveiled at GTC Berlin, co-designs protein sequences and structures while handling biomolecules like sugars, DNA, and RNA in a unified space. It runs 13 times faster than prior models on 200-residue designs, topping benchmarks in binding, enzyme tasks, and more, with lab validations including HIV drug-synthesizing enzymes at 79% conversion. Open-source via GitHub, Hugging Face, and NVIDIA NIM, it lowers barriers for researchers in drug discovery and beyond, as Kieran Didi noted its superior in silico and lab results. (Grok summary, last updated ~35 minutes ago)", "posts": [{"id": "2112886081326927895", "url": "https://x.com/DidiKieran/status/2112886081326927895", "text": "Avengers assemble: 1 year BakerLab + NVIDIA GenAIR = 🔥 https://rfd4-proteina.org\n\nPresenting RFD4-Proteina, our latest protein design model, significantly better and faster than everything we compared against, both in silico and in the lab! 1/30", "name": "Kieran Didi", "handle": "DidiKieran", "avatar": "https://pbs.twimg.com/profile_images/1889078529955962880/fnG7vqzj_200x200.jpg", "likes": 535, "rts": 172, "replies": 20, "views": 44483, "ts": 1792586271, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112881941775335425/vid/avc1/1280x720/62TROu2z70nND-dJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112881941775335425/vid/avc1/1920x1080/BwE-BVtkBrxnbX1u.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112881941775335425/img/-s4zvMP4t5ANp6V_.jpg", "dur": 187}], "quote": null, "reply_to": null}, {"id": "2112875578873487424", "url": "https://x.com/NVIDIAHealth/status/2112875578873487424", "text": "🧪 @UWproteindesign + 💚 NVIDIA = 👶 RFD4-Proteina\n\nProud parents ✨ Gifted kid", "name": "NVIDIA Healthcare", "handle": "NVIDIAHealth", "avatar": "https://pbs.twimg.com/profile_images/1864479660530438144/NJZZqouX_200x200.jpg", "likes": 209, "rts": 45, "replies": 4, "views": 15600, "ts": 1792583767, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112874246720618497/vid/avc1/1280x720/X4kNT4pl_yBIthUU.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112874246720618497/vid/avc1/3840x2160/CIEOjG9l57U9V_lQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112874246720618497/img/VjRK5XNhiOfxZZEQ.jpg", "dur": 187}], "quote": null, "reply_to": null}, {"id": "2112874890613145982", "url": "https://x.com/anthonycosta/status/2112874890613145982", "text": "Introducing RFD4-Proteina! A monumental advance in protein design! Diverse frontier capabilities across design tasks and biological modalities from the combined strength of the @UWproteindesign RFdiffusion and @NVIDIAHealth Proteina lineage of models. Available open source, through our partners, and as an NVIDIA NIM.", "name": "Anthony Costa", "handle": "anthonycosta", "avatar": "https://pbs.twimg.com/profile_images/1948588976299720704/gaVUHjTl_200x200.jpg", "likes": 83, "rts": 29, "replies": 2, "views": 5448, "ts": 1792583603, "media": [], "quote": {"id": "2112851150361842058", "url": "https://x.com/nvidianewsroom/status/2112851150361842058", "text": "NVIDIA and @UWproteindesign introduce RFD4-Proteina, an open model to design proteins and refine candidates for lab testing, paving the way for new medicines and diagnostics.\n\nAnnounced at GTC Berlin: https://nvda.ws/4ywvAss", "name": "NVIDIA Newsroom", "handle": "nvidianewsroom", "avatar": "https://pbs.twimg.com/profile_images/2081770046141919232/XxJ5pb1I_200x200.jpg", "likes": 76, "rts": 15, "replies": 2, "views": 9181, "ts": 1792577943, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJa7HyW8AAdO-X.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792595382, "post_ids": ["2112886081326927895", "2112875578873487424", "2112874890613145982"]}, {"headline": "LiteLLM Python Library Hit by Malicious Package Infostealer", "meta": "Explore · News · Trending now · News · 343 posts", "url": "https://x.com/i/trending/2112910609545371994", "summary": "LiteLLM version 1.107.0, released on PyPI on October 21, 2026, contained malicious code in all seven platform wheels that deploys a credential stealer targeting SSH keys, cloud credentials from AWS, GCP, and Azure, browser passwords, and AI tokens like those for Claude and Copilot. The malware also sets up a persistent backdoor for remote access, exfiltrating data to www.litellm.dev and polling for attacker commands. PyPI removed the package quickly after alerts from JFrog, Aikido, and others, but users who installed it must isolate systems, rotate all credentials, and switch to safe versions like 1.106.2. This marks the second supply chain attack on LiteLLM this year, underscoring risks in open-source AI tools. (Grok summary, last updated ~36 minutes ago)", "posts": [{"id": "2112882176156909646", "url": "https://x.com/JFrogSecurity/status/2112882176156909646", "text": "🚨 JFrog Security Research has identified a supply-chain attack involving malicious code in the LiteLLM 1.107.0 PyPI release. Avoid this version and investigate environments where it was installed or executed. More details will be shared soon in our blog post.", "name": "JFrog Security", "handle": "JFrogSecurity", "avatar": "https://pbs.twimg.com/profile_images/1894980264910045184/ubG4I84I_200x200.png", "likes": 1286, "rts": 152, "replies": 29, "views": 301728, "ts": 1792585340, "media": [], "quote": null, "reply_to": null}, {"id": "2112892021170151795", "url": "https://x.com/AikidoSecurity/status/2112892021170151795", "text": "❗️LiteLLM was compromised (Again). The latest version 1.107.0 contains an infostealer and RAT.\n\nAll 7 compiled wheels are backdoored. Anyone who ran pip install litellm==1.107.0 on any platform should assume credentials are compromised.\n\nMore details soon!", "name": "Aikido", "handle": "AikidoSecurity", "avatar": "https://pbs.twimg.com/profile_images/2086803726346735616/s0dTBGM1_200x200.jpg", "likes": 257, "rts": 66, "replies": 26, "views": 49701, "ts": 1792587688, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKAFxtbkAAF9Nw.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112907732877775016", "url": "https://x.com/SocketSecurity/status/2112907732877775016", "text": "🚨 LiteLLM, a Python package for connecting to AI model providers with 92M+ monthly downloads, has been compromised.\n\nVersion 1.107.0 ships credential-stealing malware through PyPI wheels and Docker images, targeting cloud credentials, developer secrets, and AI tools.", "name": "Socket", "handle": "SocketSecurity", "avatar": "https://pbs.twimg.com/profile_images/2057141188591824896/aKdKFNEE_200x200.jpg", "likes": 1777, "rts": 307, "replies": 100, "views": 261182, "ts": 1792591434, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKNz_RWYAAoI1O.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792595382, "post_ids": ["2112882176156909646", "2112892021170151795", "2112907732877775016"]}, {"headline": "Jensen Huang Charms Crowd with Microduck Robots at GTC Berlin", "meta": "Explore · Trending · Trending now · News · 295 posts", "url": "https://x.com/i/trending/2112915355857465635", "summary": "During his GTC Berlin keynote, Jensen Huang brought four 25-cm Microducks from Pollen Robotics onstage, guiding the bipedal bots (one tripped and recovered) to highlight NVIDIA's push into physical AI and robotics; he explained NVIDIA's roadmap to them, tying it to Europe becoming a thriving AI economy, with Isaac platform expansions, humanoid systems, and tools bridging virtual training to real-world use. (Grok summary, last updated ~15 minutes ago)", "posts": [{"id": "2112856720741740719", "url": "https://x.com/nvidia/status/2112856720741740719", "text": "Even Microducks need a nap. 😴", "name": "NVIDIA", "handle": "nvidia", "avatar": "https://pbs.twimg.com/profile_images/1828904711124078593/SRvCZSfQ_200x200.jpg", "likes": 3150, "rts": 309, "replies": 133, "views": 302451, "ts": 1792579271, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112855833302167552/vid/avc1/1280x720/nLcz4_GCOwmLFJ5f.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112855833302167552/vid/avc1/3840x2160/c9OFG-iYIP5lqIGY.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112855833302167552/img/X7kV5ZQfQwbzJyJa.jpg", "dur": 53}], "quote": null, "reply_to": null}, {"id": "2112855959609729106", "url": "https://x.com/NVIDIAAI/status/2112855959609729106", "text": "\"There's no question everybody will become an AI company and we're going to have a thriving AI economy here in Europe.\"", "name": "NVIDIA AI", "handle": "NVIDIAAI", "avatar": "https://pbs.twimg.com/profile_images/2055340743552831488/me-KUIug_200x200.png", "likes": 2116, "rts": 248, "replies": 89, "views": 84907, "ts": 1792579090, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112855829066264576/vid/avc1/1280x720/rqRUXk1ja5SeExOq.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112855829066264576/vid/avc1/3840x2160/8t6W9ALtMz584-Cj.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112855829066264576/img/BK3Kd4HzlFAMUAJU.jpg", "dur": 7}], "quote": null, "reply_to": null}, {"id": "2112863605788168508", "url": "https://x.com/Thom_Wolf/status/2112863605788168508", "text": "Jensen spent 10 min of his keynote asking microducks to sit, then explained Nvidia's roadmap to them 🥹", "name": "Thomas Wolf", "handle": "Thom_Wolf", "avatar": "https://pbs.twimg.com/profile_images/2068682157451571200/_ZNKM_5E_200x200.jpg", "likes": 1382, "rts": 129, "replies": 61, "views": 120229, "ts": 1792580913, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112863386924957696/vid/avc1/480x852/d-Z2VFnNsHVnGvML.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112863386924957696/vid/avc1/720x1280/VYi4puA3KhK3c8Og.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112863386924957696/img/AOKvlyBevbc-15Uv.jpg", "dur": 249}], "quote": null, "reply_to": null}], "captured": 1792595382, "post_ids": ["2112856720741740719", "2112855959609729106", "2112863605788168508"]}]);